mapper.select:
select A.*, B.username, CASE A.order_type WHEN 'goods' THEN G.name ELSE T.title END as title, CASE A.order_type WHEN 'goods' THEN G.img ELSE T.cover END as cover, CASE A.order_type WHEN 'goods' THEN G.price ELSE T.price END as price from b_order as A join b_user as B on (A.user_id=B.id) left join b_thing as T on (A.thing_id=T.id AND (A.order_type IS NULL OR A.order_type = 'thing')) left join goods as G on (A.thing_id=G.id AND A.order_type = 'goods') where 2>1
and A.user_id=#{userId}
and A.status=#{status}
order by A.order_time desc;
